#' Read JACUSA2 result file
#'
#' \code{read_result()} reads data that was generated by JACUSA2 and creates a JACUSA2 result object.
#'
#' @param file String that represents the file name of the JACUSA2 output or an URL.
#' @param unpack Boolean unpack info field.
#' @param tmpdir String @see `data.table::fread`.
#' @param showProgress Boolean @see `data.table::fread`.
#' @param ... parameters forwarded to `data.table::fread`.
#'
#' @return RangedExperiment object representing JACUSA2 result
#'
#'
#' @export
read_result <- function(file, unpack = TRUE, tmpdir = tempdir(), showProgress = FALSE, ...) {
  # if url download first
  if (grepl("ftp://|http://", file)) {
    # partly adopted from data.table::fread
    tmpFile <- tempfile(tmpdir = tmpdir)
    if (!requireNamespace("curl", quietly = TRUE))
      stop("Input URL requires https:// connection for which fread() requires 'curl' package which cannot be found. Please install 'curl' using 'install.packages('curl')'.")

    tmpFile = tempfile(fileext = paste0(".", tools::file_ext(file)), tmpdir = tmpdir)
    curl::curl_download(file, tmpFile, mode = "wb", quiet = !showProgress)
    file = tmpFile
    on.exit(unlink(file), add = TRUE)
  }

  # pre process file
  # parse comments ^(#|##) to determine result/method type and number of conditions
  fun <- ifelse(grepl('\\.gz$', file), base::gzfile, base::file)
  con <- fun(file, "r")
  cond_count <- 0
  # FIXME - implement
  # if (length(cond_desc) > 0) {
  #   cond_count <- length(cond_desc)
  # }
  skip_lines <- 0
  header_names <- NULL
  jacusa_header <- c()
  # possible result/method types: unknown, call, pileup, rt-arrest, lrt-arrest
  type <- .UNKNOWN_METHOD
  while (TRUE) {
    line = readLines(con, n = 1)
    # quit reading: nothing to read or first no header line
    if (length(line) == 0 || length(grep("^#", line)) == 0) {
      break
    }
    # count header lines to ignore
    skip_lines <- skip_lines + 1

    if (length(grep("^#contig", line)) > 0) {
      # try to guess result/method by header line
      type <- .guess_file_type(line)
      # type will be valid or .guess_file_type throw error

      # parse and store header
      # fix header: #contig -> contig
      header_names <- sub("^#", "", line);
      header_names <- unlist(base::strsplit(header_names, split = "\t", fixed = TRUE))

      # guess number of conditions
      guessed_cond_count <- .guess_cond_count(type, header_names)
      if (cond_count > 0) {
        if (guessed_cond_count != cond_count) {
          stop("Length of description(",
               cond_count,
               ") and conditions(", guessed_cond_count, ") don't match.")
        }
      }
      cond_count <- guessed_cond_count
    } else if (length(grep("^##", line)) > 0) {
        jacusa_header <- c(gsub("^##", "", line), jacusa_header)
    }

  }
  # finished pre-processing
  close(con)

  # check that JACUSA2 invocation line could be parsed
  if (is.null(jacusa_header)) {
    warning("No JACUAS2 invocation line for file: ", file)
  }

  # check that a header could be parsed
  if (is.null(header_names)) {
    stop("No header line for file: ", file)
  }

  # check that conditions could be guessed
  if (cond_count < 1) {
    stop("Conditions could not be guessed for file: ", file)
  }

  # read data
  data <- data.table::fread(
    file,
    skip = skip_lines,
    sep = "\t",
    header = FALSE,
    ...
  )
  colnames(data) <- header_names
  # convert to numeric
  i <- data[, 5] == .EMPTY
  if (any(i)) {
    data[i, 5] <- NA
    data[, 5] <- as.numeric(data[, 5])
  }

  prefixes <- .type2prefix(type)
  match_cols <- .match_cols(data, prefixes, cond_count)
  cond_repl <- match_cols |>
    dplyr::filter(prefix == prefixes[1]) |>
    dplyr::select(cond, repl, sample)
  unpacked_info <- unpack_info(data$info)

  colData <- .create_colData(cond_repl, jacusa_header = jacusa_header)
  rowRanges <- .create_rowRanges(data)
  assays <- .unpack_cols(data, match_cols, .BASES)

  # parse indels
  for (indel in c("insertions", "deletions")) {
    if (grepl(paste0("^", indel), colnames(unpacked_info))) {
      res <- .add_indels(indel, unpacked_info, cond_repl, assays, rowRanges)
      rowRanges <- res$rowRanges
      assays <- res$assays
    }
  }
  # add estimation info
  rowRanges <- .add_estimate_info(unpacked_info, cond_count, rowRanges)
  if ("score_subsampled" %in% colnames(unpacked_info)) {
    GenomicRanges::mcols(rowRanges)[, "score_subsampled"] <- strsplit(unpacked_info[, "score_subsampled"], ",")
  }

  if (type %in% c(.RT_ARREST, .LRT_ARREST)) {
    GenomicRanges::mcols(rowRanges)[, "arrest_score"] <- as.numeric(unpacked_info[, "arrest_score"])
  }
  
  # add extra infos
  assays <- .add_numeric_vector(unpacked_info, "reads", cond_count)
  assays <- .add_numeric_vector(unpacked_info, "non_ref_ratio", cond_count)
  assays <- .add_numeric_vector(unpacked_info, "base_ratio", cond_count)
  
  metadata <- list()
  if (is.null(jacusa_header)) {
    metadata[["command"]] <- jacusa_header
  }
  
  browser()
  se <- SummarizedExperiment::SummarizedExperiment(assays = lapply(assays, tibble::as_tibble),
                                                   rowRanges = rowRanges,
                                                   colData = colData,
                                                   metadata = metadata)

  se
}

.add_indels <- function(indel, unpacked_info, cond_repl, assays, rowRanges) {
  stopifnot(indel %in% c("insertion", "deletion"))

  cond_count <- cond_repl |>
    dplyr::pull(cond) |>
    unique() |>
    length()

  # set score and pvalue
  keys <- c(paste0(indel, "_score"), paste0(indel, "_pvalue"))
  GenomicRanges::mcols(rowRanges) <- as.numeric(unpacked_info[, c(keys)])

  subsampled_key <- paste0(indel, "_score_subsampled")
  if (subsampled_key %in% colnames(unpacked_info)) {
    GenomicRanges::mcols(rowRanges)[, subsampled_key] <- strsplit(unpacked_info[, subsampled_key], ",")
  }

  ratio_key <- paste0(indel, "_ratio")
  count_key <- paste0(indel, "s")
  for (key in c(ratio_key, count_key)) {
    assays <- .add_numeric_vector(unpacked_info, key, cond_count)
  }

  list("assays" = assays,
       rowRanges = rowRanges)
}

