.create_rowRanges <- function(data) {
  rowRanges <- GenomicRanges::GRanges(
    seqnames = data$contig,
    ranges = IRanges::IRanges(start = data$start + 1, end = data$end),
    strand = GenomicRanges::strand(gsub("\\.", "*", data$strand))
  )

  GenomicRanges::mcols(rowRanges)[, c("filter", "ref")] <- data[, c("filter", "ref")]

  rowRanges
}

.create_colData <- function(cond_repl, conditions = NULL, jacusa_header = NULL) {
  samples <- unique(cond_repl$sample)
  if (is.null(conditions)) {
    conditions <- paste0("cond_", cond_repl$cond)
  } else {
    conditions <- mapply(function(label, n) { rep(label, n)},
                         conditions, table(cond_repl$cond),
                         SIMPLIFY = FALSE) |>
      unlist(use.names = FALSE)
  }
  df <- data.frame(library = rep("unknown", length(samples)),
                   condition = conditions,
                   row.names = samples)

  df
}

