#' Observed base calls.
#' 
#' Observed base calls.
#' 
#' @param bases tibble of base call counts
#' @return vector of observed base calls
#' @export
base_call <- function(bases) {
  apply(bases > 0, 1, function(x) {
    paste0(names(which(x)), collapse = "") 
    }
  )
}

.add_numeric_vector <- function(df, prefix, assays, cond_count) {
  match_cols <- .match_cols(df, c(prefix), cond_count)
  if (is.null(match_cols)) {
    return(assays)
  }
  missing_cols <- setdiff(match_cols$col, colnames(df))
  if (length(missing_cols)) {
    df[, missing_cols] <- 0
  }
  values <- df[, match_cols$col] |> 
    as.numeric()
  colnames(values) <- match_cols$sample
  assays[[prefix]] <- values

  assays
}

# match columns from df  that are prefixed with types
.match_cols <- function(df, prefixes, cond_count) {
  # regex parts:
  prefix_regex = paste0("^(", paste0(prefixes, collapse = "|"), ")")
  cond_regex = paste0("([0-9]{", nchar(cond_count), "})")
  repl_regex = "([0-9]+)"

  # get relevant cols and disect to m(atch):
  # match, base_type, condition, replicate
  m <- do.call(
    rbind, 
    regmatches(names(df), regexec(paste0(prefix_regex, cond_regex, repl_regex), names(df)))
  )

  if (any(dim(m) == 0)) {
    return(NULL)
  }

  col_names <- c("col", "prefix", "cond", "repl")
  if (ncol(m) != length(col_names)) {
    m <- matrix(character(), 0, length(col_names))
  }
  colnames(m) <- c("col", "prefix", "cond", "repl")
  match_cols <- as.data.frame(m, stringsAsFactors = FALSE)
  match_cols$sample <- paste("bam", match_cols$cond, match_cols$repl, sep = "_")
  
  match_cols
}

.cond_repl <- function(match_cols) {
  match_cols |>
    dplyr::filter(prefix == match_cols$prefix[1]) |>
    dplyr::select(cond, repl, sample)
}

# replace empty with actual values
.fill_empty <- function(df, cols, new_cols) {
  new_value <- paste0(rep(0, length(new_cols)), collapse = ",")

  for (col in cols) {
    i <- df[, col] == .EMPTY | df[, col] == ""
    if (length(i)) {
      df[i, col] <- new_value
    }
  }

  df
}

#' Get keys of info field.
#' 
#' Get keys of info field.
#' 
#' @param info Vector of strings.
#' @return returns a vector of available keys.
#' 
#' @export
get_info_keys <- function(info) {
  keys <- base::strsplit(gsub("(;?[^=;]+)=[^=;]+", "\\1", info), ";", fixed = TRUE) |>
    unlist() |>
    unique()
  
  setdiff(keys, .EMPTY)
}

#' Unpack info field
#' 
#' Unpacks info field.
#' 
#' @param info Vector of stings.
#' @param cond_count integer Number of conditions.
#' @param keys vector of string of keys to extract from "info".
#' @return returns a JACUSA2 result object with "info" unpacked.
#' 
#' @export
unpack_info <- function(info, keys = get_info_keys(info)) {
  if (is.null(keys) || length(keys) == 0) {
    return(NULL)
  }

  info <- fast_unpack_info(info, names = keys) |>
    as.data.frame()

  info
}


.add_estimate_info <- function(unpacked_info, cond_count, rowRanges) {
  cols <- c(paste0("reset", c(1:cond_count, "P")), paste0("backtrack", c(1:cond_count, "P")))
  for (col in cols) {
    if (col %in% colnames(unpacked_info)) {
      i <- unpacked_info[, col] == ""
      unpacked_info[i, col] <- NA
    } else {
      unpacked_info[, col] <- NA
    }
  }
  GenomicRanges::mcols(rowRanges)[, cols] <- unpacked_info[, cols]
  
  rowRanges
}

# expand strings from vector s
.unpack <- function(s, new_cols) {
  df <- lapply(data.table::tstrsplit(s, split = ",", fixed = TRUE), as.numeric) %>% 
    as.data.frame()
  colnames(df) <- new_cols
  
  tibble::as_tibble(df)
}

# expand cols -> string to numeric
.unpack_cols <- function(df, match_cols, new_cols) {
  cols <- unique(match_cols$col)
  df <- .fill_empty(df, cols, new_cols)

  unpacked <- lapply(df[cols], .unpack, new_cols = new_cols)

  names(unpacked) <- match_cols$sample
  l <- split(unpacked, match_cols$prefix)

  l
}
